// === Tab: mySketch.js ===
/* Created for #WCCChallenge "Cube"

This is just a port of someone ele's cool cube animation.  Where possible, I have updated code to use Lygia when
porting this code from shaderToy. In many cases there was no comparable function.
This original shader uses clever logic to move the cubes in alternating axes. It also offsets the camera in the x and z directions. 
I am not sure the sound effect quite works. Suggested improvements are welcome!


AI Discloure: I asked chatGPT to explain the function of some parts of the shader code.

Port of https://www.shadertoy.com/view/MlsGRS by dila
Pnch sound effect (royalty free) by Duc5687:
https://pixabay.com/sound-effects/film-special-effects-punch-sound-effect-7ehhx2evi5k-500092/
https://tonejs.github.io
https://editor.p5js.org/thomasjohnmartinez/sketches/eQQsm5apX
https://github.com/processing/p5.sound.js
https://github.com/processing/p5.sound.js/issues/54
*/

let cubeShader;
let showOriginal = false;
let player, soundSource;

async function setup() {
	let canvasSize = max(windowWidth, windowHeight)
	let cnv = createCanvas(windowWidth, windowHeight, WEBGL);
	cnv.mousePressed(playSound);

	soundSource = await loadSound("https://openprocessing.org/sketch/2904289/files/punch-sound.mp3")

	pixelDensity(1)
	noStroke()


	cubeShader = await createShader(resolveLygia(vert), resolveLygia(frag))
	if (showOriginal) {
		cubeShader = await createShader(resolveLygia(vert), resolveLygia(original))
	}

	btn = createButton("Add Sound Effect");
   btn.position(6, 10);
   btn.mousePressed(playSound);
   soundSource.loop();
}

function playSound() {
  soundSource.play();
}

