// 	player.autostart = true;
// }

function draw() {
	cubeShader.setUniform('u_resolution', [width, height]);
	cubeShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
	cubeShader.setUniform("u_time", millis() / 1000.0)
	cubeShader.setUniform("iFrame", frameCount);
	shader(cubeShader);

	rect(0, 0, width, height);
}

// === Tab: box.js ===
const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`

const frag = `#version 300 es
precision highp float;
out vec4 O;

uniform vec2 u_resolution; 
uniform float u_time;
uniform vec2 u_mouse;

#include "lygia/math/const.glsl"
#include "lygia/math/rotate3d.glsl"
#include "lygia/math/map.glsl"
#include "lygia/space/ratio.glsl"
#include "lygia/animation/easing/quadraticInOut.glsl"
#include "lygia/math/rotate2d.glsl"
#include "lygia/math/rotate3dX.glsl"
#include "lygia/math/rotate3dY.glsl"
#include "lygia/math/rotate3dZ.glsl"
#include "lygia/color/space/linear2gamma.glsl"
#include "lygia/sdf.glsl"

// This function finds a time-dependent axis to move by flooring animation speed (u_time*speed )
// This returns either 0.0, 1.0, or 2.0
vec3 determineAxisToMove( vec3 pos, vec3 gmod, vec3 rmod ) {
    //float speed = 1.0;
    float g = floor(mod(u_time,3.0));
	    if (g==2.0){
	    // only move cells where both x & y are odd
	        if (gmod.y*gmod.x==1.0) {
		         // move in z direction by offset
	            pos.z += rmod.y*rmod.x*0.5;
	        }
	    } else if (g==0.0){
	        if (gmod.y*gmod.z==1.0) {
	            pos.x += rmod.y*rmod.z*0.5;
	        }
	    } else if (g==1.0){
	        if (gmod.z*gmod.x==1.0) {
	            pos.y += rmod.z*rmod.x*0.5;
	        }
	    }

	 return pos;
}

vec3 remapToCell( vec3 pos ) {
    vec3 grid = floor(pos); // convert to grid coordinates
    pos = pos - grid;  // move into local cell 
    return pos * 2.0 - 1.0; // remap into center of cell
}

float addCheckerPattern( vec3 pos, vec3 grid, float r ) {
  // float d = boxFrameSDF(pos,vec3(r), 0.01);

   float d = boxSDF(pos,vec3(r));
   bool skip = false;
   // skip if both x and y are even
   if (mod(grid.x,2.0)==0.0 && mod(grid.y,2.0)==0.0) {
       skip = true;
   }

    if (mod(grid.x,2.0)==0.0 && mod(grid.z,2.0)==0.0) {
        skip = true;
    }

    if (mod(grid.y,2.0)==0.0 && mod(grid.z,2.0)==0.0) {
        skip = true;
    }

    if (skip) {
        d = 100.0;
        vec3 off = vec3(2.0,0.0,0.0);
        for (int i = 0; i < 3; ++i) {
		      // float a = boxFrameSDF(pos+off,vec3(r), 0.01);
		      // float b = boxFrameSDF(pos-off,vec3(r), 0.01);
            float a = boxSDF(pos + off,vec3(r));
            float b = boxSDF(pos - off,vec3(r));
            d = min(d,min(a,b));
            off = off.zxy;
        }
        d *= 0.5;
    } else {
        d *= 0.8;   
    }   
    return d;
}


float map(vec3 pos)
{
    float speed = 1.0;
    vec3 grid = floor(pos); // convert pos to integer grid coordinates
    vec3 gmod = mod(grid, 2.0); // creates a checkerboard pattern:  (1,1,1) => odd, (0,0,0) => even
    vec3 rmod = mod(grid, 4.0) - 2.0; // directional offset vector
    float tm = fract(u_time * speed);
    rmod *= (cos(tm*PI)-1.0);

    pos = determineAxisToMove( pos, gmod, rmod );

    pos = remapToCell( pos );


    float r = 0.9;
	 return addCheckerPattern(pos, grid, r);
   // return d;
}

vec3 surfaceNormal(vec3 pos) {
 	vec3 delta = vec3(0.01, 0.0, 0.0);
    vec3 normal;
    normal.x = map(pos + delta.xyz) - map(pos - delta.xyz);
    normal.y = map(pos + delta.yxz) - map(pos - delta.yxz);
    normal.z = map(pos + delta.zyx) - map(pos - delta.zyx);
	 return normalize(normal);
}


vec3 cubeGrid (vec2 st) {
    vec3 eye = normalize(vec3(st, 1.0 - dot(st, st) * 0.33));

    vec3 origin = vec3(0.0);

    eye = eye * rotate3dY(u_time*0.5) * rotate3dX(u_time*0.5);

    float speed = 0.1;

    float j = u_time * speed;

    float f = fract(j);

	 // Easing function 
    f = quadraticInOut(f);  
    f = map(f, 0.0, 1.0, -1.0, 1.0);

    // Create alternating camera offset
	 float a = floor(j) + f * floor(mod(j,2.0));
    float b = floor(j) + f * floor(mod(j+1.0,2.0));

	  // Offset camera origin in x and z direction
    origin.x += 0.5 + a;
    origin.y += 0.5;
    origin.z += -0.5 + b;

    float t = 0.0;
    float d = 0.0;

	// Raymarching
   // I tried substituting Lygia's raymarch function but it doesn't work in this case 

    for (int i = 0; i < 32; ++i){
        vec3 pos = origin + eye * t;
        d = map(pos);
        t += d;
    }

    vec3 worldPos = origin + eye * t;

    vec3 norm = surfaceNormal(worldPos);

    float prod = max(0.0, dot(norm, -eye));

    float amb = 0.0;

    vec3 ref = reflect(eye, norm);

    vec3 spec = vec3(0.0);

    prod = pow(1.0 - prod, 2.0);

    //vec3 col =vec3(0.1, 0.3, 0.5);

	  vec3 col = vec3(0.356, 0.3725, 0.592); // royal blue
     spec *= col;

    col = mix(col, spec, prod);

    float shade = pow(max(1.0 - amb, 0.0), 4.0);

	 float fog = 1.0/(1.0 + t * t *0.2) * shade;

    vec3 final = col;

    //final = mix(final, vec3(1.0), fog);

    final = mix(final, vec3(1., 0.419, 0.424), fog); // mix with bright pink

    fog = 1.0 / (1.0 + t * t * 0.1);
    return final*fog;

}

void main( )
{
   vec2 pixel = 1.0/u_resolution;
   vec2 uv = gl_FragCoord.xy * pixel;
   vec2 st = uv*2.0 - 1.0;
   st = ratio(st, u_resolution.xy);

   vec3 color = cubeGrid(st);
   color = linear2gamma(color);

   O = vec4(color, 1.0);

}`

